import datetime

holidays = {datetime.date(2026,10,12)}

def is_business_day(d):
    return d.weekday() < 5 and d not in holidays

def add_business_days_inclusive(start, duration):
    # returns end date of a phase that starts on 'start' and runs 'duration' business days inclusive
    d = start
    count = 0
    while count < duration:
        if is_business_day(d):
            count += 1
            if count == duration:
                return d
        d += datetime.timedelta(days=1)
    return d

def next_business_day(d):
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d):
        d += datetime.timedelta(days=1)
    return d

start = datetime.date(2026,10,5)
print("Start date weekday:", start.strftime("%A"))

phases = [("Discovery",3), ("Build",6), ("QA",4), ("Release",1)]

current_start = start
for name, dur in phases:
    # ensure current_start is a business day
    while not is_business_day(current_start):
        current_start = next_business_day(current_start - datetime.timedelta(days=1))
    end = add_business_days_inclusive(current_start, dur)
    print(f"{name}: start {current_start} ({current_start.strftime('%A')}), duration {dur} business days, end {end} ({end.strftime('%A')})")
    current_start = next_business_day(end)

print("Stated launch date: 2026-10-22")
EOF
